// Client for the counter program, generated by TypeSOL from its IDL. Do not edit: `typesol build` (or `typesol client`) rewrites it.
import {
  AccountRole,
  type Address,
  type Codec,
  type FetchAccountConfig,
  type GetAccountInfoApi,
  type Instruction,
  type ProgramDerivedAddress,
  type ReadonlyUint8Array,
  type Rpc,
  SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM,
  type TransactionSigner,
  address,
  fetchEncodedAccount,
  getAddressCodec,
  getAddressEncoder,
  getProgramDerivedAddress,
  getStructCodec,
  getU64Codec,
  getU8Codec,
  isSolanaError,
} from "@solana/kit";

export const PROGRAM_ADDRESS = address("<program>");

// ---- Helpers ----
const concat = (parts: ReadonlyUint8Array[]): Uint8Array => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) out.set(p, (at += p.length) - p.length);
  return out;
};
const hasPrefix = (data: ReadonlyUint8Array, prefix: ReadonlyUint8Array) => data.length >= prefix.length && prefix.every((b, i) => data[i] === b);
const isSigner = (v: TransactionSigner | Address): v is TransactionSigner => typeof v === "object" && v !== null && "address" in v;
const key = (v: TransactionSigner | Address | undefined | null): Address => {
  if (v === undefined || v === null) throw new Error("a seed account is missing");
  return isSigner(v) ? v.address : v;
};
const required = <T>(v: T | undefined, name: string): T => {
  if (v === undefined) throw new Error("account " + name + " is required");
  return v;
};
const meta = (v: TransactionSigner | Address, role: AccountRole) => (isSigner(v) ? { address: v.address, role, signer: v } : { address: v, role });

// ---- Types ----
export interface Counter {
  authority: Address;
  count: bigint;
  bump: number;
}
export interface CounterArgs {
  authority: Address;
  count: number | bigint;
  bump: number;
}
export function getCounterCodec(): Codec<CounterArgs, Counter> {
  return getStructCodec([["authority", getAddressCodec()], ["count", getU64Codec()], ["bump", getU8Codec()]]) as unknown as Codec<CounterArgs, Counter>;
}

// ---- Accounts ----
const CounterAccount_DISCRIMINATOR = new Uint8Array([255, 176, 4, 245, 188, 253, 124, 25]);
/** Counter account data: the 8-byte discriminator, then the fields. */
const CounterAccount = {
  discriminator: CounterAccount_DISCRIMINATOR,
  decode(data: ReadonlyUint8Array): Counter {
    if (!hasPrefix(data, CounterAccount_DISCRIMINATOR)) throw new Error("not a Counter account (discriminator mismatch)");
    return getCounterCodec().decode(data, 8);
  },
  encode(value: CounterArgs): ReadonlyUint8Array {
    return concat([CounterAccount_DISCRIMINATOR, getCounterCodec().encode(value)]);
  },
  async fetch(rpc: Rpc<GetAccountInfoApi>, at: Address, config?: FetchAccountConfig): Promise<Counter> {
    const found = await fetchEncodedAccount(rpc, at, config);
    if (!found.exists) throw new Error("Counter account does not exist: " + at);
    return CounterAccount.decode(found.data);
  },
  async fetchMaybe(rpc: Rpc<GetAccountInfoApi>, at: Address, config?: FetchAccountConfig): Promise<Counter | null> {
    const found = await fetchEncodedAccount(rpc, at, config);
    return found.exists ? CounterAccount.decode(found.data) : null;
  },
};

// ---- Instructions ----
export interface InitializeAccounts {
  authority: TransactionSigner | Address;
  counter?: Address;
  systemProgram?: Address;
}
/** Create the caller's counter at PDA ["counter", authority]. */
async function buildInitialize(input: InitializeAccounts): Promise<Instruction> {
  const $authority = input.authority;
  const $systemProgram = input.systemProgram ?? address("11111111111111111111111111111111");
  const $counter = input.counter ?? (await getProgramDerivedAddress({ programAddress: PROGRAM_ADDRESS, seeds: [new Uint8Array([99, 111, 117, 110, 116, 101, 114]), getAddressEncoder().encode(key($authority))] }))[0];
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($authority, "authority"), AccountRole.WRITABLE_SIGNER),
      meta($counter, AccountRole.WRITABLE),
      meta($systemProgram, AccountRole.READONLY),
    ],
    data: new Uint8Array([175, 175, 109, 31, 13, 152, 155, 237]),
  } as Instruction;
}

export interface IncrementAccounts {
  authority: TransactionSigner | Address;
  counter: Address;
}
export interface IncrementArgs {
  by: number | bigint;
}
async function buildIncrement(input: IncrementAccounts, args: IncrementArgs): Promise<Instruction> {
  const $authority = input.authority;
  const $counter = input.counter;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($authority, "authority"), AccountRole.READONLY_SIGNER),
      meta(required($counter, "counter"), AccountRole.WRITABLE),
    ],
    data: concat([new Uint8Array([11, 18, 104, 9, 104, 174, 59, 33]), getStructCodec([["by", getU64Codec()]]).encode(args)]),
  } as Instruction;
}

export interface AssertAtLeastAccounts {
  counter: Address;
}
export interface AssertAtLeastArgs {
  min: number | bigint;
}
/** Read-only check that callers can simulate. */
async function buildAssertAtLeast(input: AssertAtLeastAccounts, args: AssertAtLeastArgs): Promise<Instruction> {
  const $counter = input.counter;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($counter, "counter"), AccountRole.READONLY),
    ],
    data: concat([new Uint8Array([217, 17, 64, 130, 131, 210, 58, 81]), getStructCodec([["min", getU64Codec()]]).encode(args)]),
  } as Instruction;
}

// ---- Errors ----
export const ERRORS: Record<number, { name: string; msg?: string }> = {
  100: { name: "InstructionMissing" },
  101: { name: "InstructionFallbackNotFound" },
  102: { name: "InstructionDidNotDeserialize" },
  2001: { name: "ConstraintHasOne" },
  2002: { name: "ConstraintSigner" },
  2004: { name: "ConstraintOwner" },
  2005: { name: "ConstraintRentExempt" },
  2006: { name: "ConstraintSeeds" },
  2007: { name: "ConstraintExecutable" },
  2009: { name: "ConstraintAssociated" },
  2012: { name: "ConstraintAddress" },
  2014: { name: "ConstraintTokenMint" },
  2015: { name: "ConstraintTokenOwner" },
  2016: { name: "ConstraintMintMintAuthority" },
  2017: { name: "ConstraintMintFreezeAuthority" },
  2040: { name: "ConstraintDuplicateMutableAccount" },
  3000: { name: "AccountDiscriminatorAlreadySet" },
  3002: { name: "AccountDiscriminatorMismatch" },
  3003: { name: "AccountDidNotDeserialize" },
  3004: { name: "AccountDidNotSerialize" },
  3005: { name: "AccountNotEnoughKeys" },
  3006: { name: "AccountNotMutable" },
  3007: { name: "AccountOwnedByWrongProgram" },
  3008: { name: "InvalidProgramId" },
  3009: { name: "InvalidProgramExecutable" },
  3010: { name: "AccountNotSigner" },
  3012: { name: "AccountNotInitialized" },
  3016: { name: "AccountReallocExceedsLimit" },
  4102: { name: "InvalidNumericConversion" },
  5100: { name: "ArithmeticOverflow" },
  5101: { name: "DivisionByZero" },
  5103: { name: "SysvarUnavailable" },
  5104: { name: "IndexOutOfBounds" },
  5105: { name: "StringTooLong" },
  5106: { name: "ReturnDataMismatch" },
  5107: { name: "EventTooLarge" },
  5108: { name: "EmptyOption" },
  5110: { name: "HeapExhausted" },
  5111: { name: "OracleRejected" },
  5112: { name: "WrongEnumVariant" },
  5113: { name: "TooManyAccounts" },
  5114: { name: "NoReturnData" },
  5115: { name: "AccountMissing" },
  6000: { name: "Unauthorized", msg: "Only the counter's authority can change it" },
  6001: { name: "RequireFailed1", msg: "counter is below the expected minimum" },
};
export type ErrorName = "InstructionMissing" | "InstructionFallbackNotFound" | "InstructionDidNotDeserialize" | "ConstraintHasOne" | "ConstraintSigner" | "ConstraintOwner" | "ConstraintRentExempt" | "ConstraintSeeds" | "ConstraintExecutable" | "ConstraintAssociated" | "ConstraintAddress" | "ConstraintTokenMint" | "ConstraintTokenOwner" | "ConstraintMintMintAuthority" | "ConstraintMintFreezeAuthority" | "ConstraintDuplicateMutableAccount" | "AccountDiscriminatorAlreadySet" | "AccountDiscriminatorMismatch" | "AccountDidNotDeserialize" | "AccountDidNotSerialize" | "AccountNotEnoughKeys" | "AccountNotMutable" | "AccountOwnedByWrongProgram" | "InvalidProgramId" | "InvalidProgramExecutable" | "AccountNotSigner" | "AccountNotInitialized" | "AccountReallocExceedsLimit" | "InvalidNumericConversion" | "ArithmeticOverflow" | "DivisionByZero" | "SysvarUnavailable" | "IndexOutOfBounds" | "StringTooLong" | "ReturnDataMismatch" | "EventTooLarge" | "EmptyOption" | "HeapExhausted" | "OracleRejected" | "WrongEnumVariant" | "TooManyAccounts" | "NoReturnData" | "AccountMissing" | "Unauthorized" | "RequireFailed1";
/**
 * The custom program error code in a failed transaction or simulation (a kit SolanaError, LiteSVM's result, a number
 * or a message), or null. The code does not say which program raised it: a program this one calls can raise the same
 * code, so check the failing instruction when that matters.
 */
export function errorCode(e: unknown): number | null {
  for (let cur: unknown = e, depth = 0; cur !== undefined && cur !== null && depth < 8; depth++) {
    if (typeof cur === "number") return cur;
    if (isSolanaError(cur, SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM)) return Number(cur.context.code);
    if (typeof cur === "object" && "err" in cur && typeof cur.err === "function") cur = String(cur.err());
    if (typeof cur === "string" || cur instanceof Error) {
      const m = /custom program error: (0x[0-9a-f]+)|Custom(?:\(|\s*\{\s*code:\s*)(\d+)/i.exec(String(cur instanceof Error ? cur.message : cur));
      if (m) return m[1] !== undefined ? Number.parseInt(m[1], 16) : Number(m[2]);
    }
    cur = typeof cur === "object" && cur !== null && "cause" in cur ? cur.cause : undefined;
  }
  return null;
}
/** Whether `e` is the error `name` (by code; see errorCode). */
export function isError(e: unknown, name: ErrorName): boolean {
  const code = errorCode(e);
  return code !== null && ERRORS[code]?.name === name;
}

// ---- Events ----
export type Event = never;
/**
 * Events in a transaction's log messages (`Program data:` lines, as `emit` writes them). Lines are matched by
 * discriminator, whichever program wrote them; lines that do not decode are skipped. `emitCpi` events travel in inner
 * instructions, not logs.
 */
export function parseEvents(logs: readonly string[]): Event[] {
  void logs;
  return [];
}

/** The counter program: instructions, accounts, PDAs, errors, events and return values. */
export const counter = {
  address: PROGRAM_ADDRESS,
  initialize: buildInitialize,
  increment: buildIncrement,
  assertAtLeast: buildAssertAtLeast,
  accounts: { Counter: CounterAccount },
  pdas: {
    /** The counter PDA (as initialize derives it). */
    counter(seeds: { authority: Address | TransactionSigner }): Promise<ProgramDerivedAddress> {
      return getProgramDerivedAddress({ programAddress: PROGRAM_ADDRESS, seeds: [new Uint8Array([99, 111, 117, 110, 116, 101, 114]), getAddressEncoder().encode(key(seeds.authority))] });
    },
  },
  returns: {
  },
  errors: ERRORS,
  errorCode,
  isError,
  parseEvents,
};
